import{z as B,x as o,o as A,c as p,q as l,j as r,D as E,d as s,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"TLS 握手","description":"","frontmatter":{"title":"TLS 握手","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tls-handshake.md","filePath":"cs/tls-handshake.md","lastUpdated":1791413859000}'),d={name:"cs/tls-handshake.md"};function D(h,a,T,c,C,m){const t=o("Mermaid");return A(),p("div",null,[a[2]||(a[2]=l('<h1 id="tls-握手" tabindex="-1">TLS 握手 <a class="header-anchor" href="#tls-握手" aria-label="Permalink to &quot;TLS 握手&quot;">​</a></h1><div class="epigraph"><p>握手一次性做完：协商版本与套件、用证书认证服务器、派生会话键，随后记录层用 AEAD 保护字节。</p><footer>—— RFC 8446, The Transport Layer Security (TLS) Protocol Version 1.3</footer></div><p><a href="/cs/transient-exec">上一课</a>把微结构泄漏标进模型。本课不谈缓存。网络课已有<a href="/cs/http-tls-entry">TLS 入口</a>：HTTPS 在 HTTP 下加一条保密管道。缺口是：握手如何把<a href="/cs/pubkey-envelope">公钥信封</a>、<a href="/cs/cert-pki">证书</a>、<a href="/cs/symmetric-crypto">AEAD</a>装成一次协议，使后续套接字字节带 CIA 的 C 与 I。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只「开始加密」不够：要防降级、要认证名字、要前向保密、要 Finished 绑定。TLS 1.3 把密钥交换收成 ECDHE（或 PSK），证书在加密之后发，减少明文元数据。缺口不是重讲 TCP 三次握手，而是记录层与握手消息的分工：明文只留下为了把会话建起来所必需的那几项。</p><p><span class="marginnote">术语翻译：前向保密就是「会话键用完即焚」。会话键来自一次性的临时 DH 份额，握手结束双方就丢掉；服务器的长期私钥只负责认证、从不参与加密。于是明年私钥泄露，也解不开今年的录音。</span></p><p><span class="marginnote">1.3 去掉了大量历史套件与 RSA 静态密钥交换，正是为了关掉「没有前向保密」与「加密但不认证」的组合。旧版本对照见网络课入口，本课以 1.3 为机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ClientHello / ServerHello 协商群与密钥份额；双方派生握手密钥与应用密钥。服务器出示证书链，用私钥证明；客户端核验证书与主机名。Finished 用 MAC 绑全部握手字节，防改套件。之后应用数据走 AEAD。本课不写报文字段表当实现抄本。</p>',9)),(A(),r(n,null,{default:E(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HELLO%5B%22Hello%3A%20%E5%AF%86%E9%92%A5%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20CERT%5B%22%E8%AF%81%E4%B9%A6%E8%AE%A4%E8%AF%81%22%5D%0A%20%20CERT%20--%3E%20FIN%5B%22Finished%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20FIN%20--%3E%20AEAD%5B%22%E8%AE%B0%E5%BD%95%E5%B1%82%20AEAD%22%5D%0A%20%20AEAD%20--%3E%20FW%5B%22%E5%90%8E%E8%AF%BE%3A%20%E9%98%B2%E7%81%AB%E5%A2%99%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"握手服务真实性 + 密钥协商；记录层服务保密与完整。这把认证协议课的「绑到会话键」做成互联网默认实例。中间盒子若要看见明文，必须成为端点（终止 TLS），从而进入另一威胁模型——后课中间人。0-RTT 用 PSK 提前发数据，有重放窗口，是可用性与安全的挤法，本课只点名。",-1)),a[5]||(a[5]=e("p",null,"证书在 1.3 里于加密后出示，减少明文元数据，不减少必须验链这一步。",-1)),(A(),r(n,null,{default:E(()=>[i(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E4%B8%AD%E9%97%B4%E4%BA%BA%E4%BB%8B%E5%85%A5%E4%BC%9A%E8%AF%9D%22%5D%20--%3E%20Q1%7B%22%E7%AF%A1%E6%94%B9%20Hello%20%E9%87%8C%E7%9A%84%E5%A5%97%E4%BB%B6%E4%B8%8E%E4%BB%BD%E9%A2%9D%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20B1%5B%22Finished%20%E6%A0%A1%E9%AA%8C%E5%85%A8%E9%83%A8%E6%8F%A1%E6%89%8B%E5%AD%97%E8%8A%82%2C%E5%A4%B1%E8%B4%A5%E5%8D%B3%E4%B8%AD%E6%AD%A2%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E5%86%92%E5%85%85%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%87%BA%E7%A4%BA%E5%81%87%E8%AF%81%E4%B9%A6%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20B2%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E9%AA%8C%E9%93%BE%E4%B8%8E%E4%B8%BB%E6%9C%BA%E5%90%8D%2C%E5%A4%B1%E8%B4%A5%E5%8D%B3%E4%B8%AD%E6%AD%A2%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20Q3%7B%22%E5%8F%AA%E5%81%B7%E5%BD%95%E6%B5%81%E9%87%8F%2C%E7%AD%89%E6%97%A5%E5%90%8E%E8%A7%A3%E5%AF%86%3F%22%7D%0A%20%20Q3%20--%3E%20B3%5B%22%E4%B8%B4%E6%97%B6%20DH%20%E4%BB%BD%E9%A2%9D%E5%B7%B2%E9%94%80%E6%AF%81%2C%E9%95%BF%E6%9C%9F%E9%92%A5%E4%B9%9F%E8%A7%A3%E4%B8%8D%E5%BC%80%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">直觉类比：Finished 像合同末页的骑缝章——双方把前面所有条款逐页压印，任何一页被偷改，章就拼不齐。历史上把套件降级到弱算法的攻击，正是被这最后一步拦下的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>TLS 不保护端点内存、不保护 DNS 若未另行认证、不保护证书误签。也不把 QUIC 的加密运输再推一遍——<a href="/cs/quic-contrast">QUIC 对照</a>已在网络课。防火墙看到的往往是已加密的流，下一课只能按连接状态而不是按 URL 过滤。</p><p>会话票与 PSK 恢复必须当密钥材料保护，否则握手再短也把长期秘密拉长暴露面。后课默认：链路在 1.3 记录层下有会话键；边界设备面对的是五元组与状态，不是明文 HTTP。</p><p>握手本身也是 DoS 面：公钥运算贵。后课可用轴会回到这里；本课先把正确协商钉死。</p><p><span class="marginnote">常见误区：以为「上了 TLS」就等于安全。TLS 的合同只覆盖传输这一段——端点内存泄漏、未认证的 DNS、被误签的证书都不在保护范围内。安全边界永远小于「用了加密」给人的直觉。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>Finished 把握手字节绑进密钥，防改套件与降级。</p></li><li><p>后课防火墙在加密流上只能看见五元组与状态。</p></li><li><p>入口课有管道；本课把 1.3 握手收成协商、证书、Finished、AEAD。</p></li><li><p>前向保密来自临时 DH；认证来自 PKI 名字绑定。</p></li><li><p>加密后过滤只能靠连接状态，是防火墙课缺口。</p></li><li><p>出处：RFC 8446；对照 Diffie–Hellman 与 AEAD 先修。</p></li></ul>',8))])}const f=B(d,[["render",D]]);export{S as __pageData,f as default};
